import os
import requests

def query_recent_error_logs():
    api_key = os.getenv("DD_API_KEY")
    app_key = os.getenv("DD_APP_KEY")
    dd_site = os.getenv("DD_SITE", "datadoghq.com")

    endpoint = f"https://api.{dd_site}/api/v2/logs/events/search"

    headers = {
        "Accept": "application/json",
        "Content-Type": "application/json",
        "DD-API-KEY": api_key,
        "DD-APPLICATION-KEY": app_key
    }

    payload = {
        "data": {
            "attributes": {
                "filter": {
                    "query": "status:error",
                    "from": "now-15m",
                    "to": "now"
                },
                "sort": "-timestamp",
                "page": {
                    "limit": 100
                }
            }
        }
    }

    response = requests.post(endpoint, headers=headers, json=payload)
    response.raise_for_status()

    logs = response.json().get("data", [])
    return [
        {
            "timestamp": log["attributes"].get("timestamp"),
            "message": log["attributes"].get("message"),
            "service": log["attributes"].get("service"),
            "status": log["attributes"].get("status")
        }
        for log in logs
    ]

if __name__ == "__main__":
    error_logs = query_recent_error_logs()
    for log in error_logs:
        print(f"[{log['timestamp']}] [{log['status']}] {log['service']}: {log['message']}")
